 void RefreshPlaces(){loading=true;places.Items.Clear();void Add(string name,string path){if(Directory.Exists(path))places.Items.Add(new Place{Name=name,Path=path});}Add("Home",Environment.GetFolderPath(Environment.SpecialFolder.UserProfile));Add("Desktop",Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory));Add("Documents",Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments));Add("Downloads",Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"Downloads"));foreach(var drive in DriveInfo.GetDrives())places.Items.Add(new Place{Name=drive.Name,Path=drive.RootDirectory.FullName});foreach(var project in DossierPreferences.Current.RecentProjects.Take(6)){var path=Path.GetDirectoryName(project);Add("Project · "+Path.GetFileName(path),path);}foreach(var path in DossierPreferences.Current.RecentFileFolders.Take(6))Add("Recent · "+Path.GetFileName(path),path);loading=false;}
